```python
from flask import Flask, request, render_template
app = Flask(__name__)

@app.route('/')
def login_page():
    return render_template('login.html')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    # Esta seção está omitida para a segurança, simulando uma tentativa de login
    print(f"Tentativa de login falha para {username} com {password}")
    return 'Login bem-sucedido'  # Simulação única

if __name__ == '__main__':
    app.run(debug=True)
```

